import com.google.common.collect.ImmutableMap;
import java.awt.image.BufferedImage;
import java.util.Map;
import lombok.Getter;
import lombok.Setter;
import static net.runelite.api.gameval.ItemID.*;

public enum Runes
{
	AIR(1, AIRRUNE),
	WATER(2, WATERRUNE),
	EARTH(3, EARTHRUNE),
	FIRE(4, FIRERUNE),
	MIND(5, MINDRUNE),
	CHAOS(6, CHAOSRUNE),
	DEATH(7, DEATHRUNE),
	BLOOD(8, BLOODRUNE),
	COSMIC(9, COSMICRUNE),
	NATURE(10, NATURERUNE),
	LAW(11, LAWRUNE),
	BODY(12, BODYRUNE),
	SOUL(13, SOULRUNE),
	ASTRAL(14, ASTRALRUNE),
	MIST(15, MISTRUNE),
	MUD(16, MUDRUNE),
	DUST(17, DUSTRUNE),
	LAVA(18, LAVARUNE),
	STEAM(19, STEAMRUNE),
	SMOKE(20, SMOKERUNE),
	WRATH(21, WRATHRUNE),
	SUNFIRE(22, SUNFIRERUNE),
	AETHER(23, AETHERRUNE),
	;

	@Getter
	private final int id;
	@Getter
	private final int itemId;

	@Getter
	@Setter
	private BufferedImage image;

	private static final Map<Integer, Runes> runes;

	static
	{
		ImmutableMap.Builder<Integer, Runes> builder = new ImmutableMap.Builder<>();
		for (Runes rune : values())
		{
			builder.put(rune.getId(), rune);
		}
		runes = builder.build();
	}

	Runes(int id, int itemId)
	{
		this.id = id;
		this.itemId = itemId;
	}

	public static Runes getRune(int index)
	{
		return runes.get(index);
	}

}
